using System;
using System.Collections.Generic;
using System.Linq;
using Newtonsoft.Json.Linq;
namespace LastRail.Presentation.Battle {
 public enum KyleFacing {FrontOpponentCarriage=1,SideOpponentCarriage=2,RearOpponentCarriage=3,TrainForward=4}
 // Presentation receipt only; caller supplies original logical time. No damage/attack-period/clock ownership.
 public sealed class KylePresentationTimeline {
  sealed class Cue {internal string Id,Motion;internal long Start;internal KyleFacing Facing;internal bool Fired,Cancelled;internal JObject Capture()=>new JObject{["id"]=Id,["motion"]=Motion,["startMs"]=Start,["facing"]=(int)Facing,["fired"]=Fired,["cancelled"]=Cancelled};}
  readonly Dictionary<string,Cue> cues=new Dictionary<string,Cue>(StringComparer.Ordinal);readonly Dictionary<string,Cue> identities=new Dictionary<string,Cue>(StringComparer.Ordinal);readonly HashSet<string> delivered=new HashSet<string>(StringComparer.Ordinal);Cue current;long last;
  readonly int[] idle,attack;public const int Capacity=1024;
  public KylePresentationTimeline(int[] idleDurations,int[] attackDurations){idle=Copy(idleDurations);attack=Copy(attackDurations);if(idle.Sum()!=1440||attack.Sum()!=1040||attack.Take(5).Sum()!=380)throw new ArgumentException("Kyle approved exposure timing required");}
  static int[] Copy(int[] d){if(d==null||d.Length!=12||d.Any(n=>n<=0))throw new ArgumentException("12 positive exposures required");return (int[])d.Clone();}
  public long LastMs=>last;public bool CanConsumeEvent(string id)=>id!=null&&cues.TryGetValue(id,out var cue)&&!cue.Cancelled;public string CueId=>current?.Id;public KyleFacing Facing=>current?.Facing??KyleFacing.FrontOpponentCarriage;public bool Attacking(long now)=>current!=null&&current.Motion=="attack"&&!current.Cancelled&&now-current.Start<1040;
  public bool Begin(CombatUnitAnimationState state,KyleFacing facing,long originalStartMs){if(state==null||state.UnitId!="op_kyle"||state.UnitRole!=CombatUnitRole.Operator||(state.AnimationKey!="idle"&&state.AnimationKey!="attack")||!Enum.IsDefined(typeof(KyleFacing),facing)||originalStartMs<0||originalStartMs>long.MaxValue-1440)throw new ArgumentException("Invalid Kyle visual cue");if(identities.TryGetValue(state.AnimationCueId,out var old)){if(old.Motion!=state.AnimationKey||old.Facing!=facing||old.Start!=originalStartMs)throw new ArgumentException("Visual cue identity conflict");if(cues.ContainsKey(old.Id))return false;var resumed=new Cue{Id=old.Id,Motion=old.Motion,Start=old.Start,Facing=old.Facing};cues.Add(resumed.Id,resumed);current=resumed;last=Math.Max(last,originalStartMs);return true;}if(identities.Count>=Capacity)throw new InvalidOperationException("Bounded visual fixture receipt capacity");var cue=new Cue{Id=state.AnimationCueId,Motion=state.AnimationKey,Start=originalStartMs,Facing=facing};cues.Add(cue.Id,cue);identities.Add(cue.Id,cue);current=cue;last=Math.Max(last,originalStartMs);return true;}
  public void EndBinding(){foreach(var cue in cues.Values)cue.Cancelled=true;}public void Cancel(){if(current!=null)current.Cancelled=true;}
  public bool Sample(long originalLogicalMs,out int frame,out bool attackMotion){if(originalLogicalMs<last||originalLogicalMs<0||current!=null&&originalLogicalMs<current.Start)throw new ArgumentException("Logical time requires original restore");last=originalLogicalMs;attackMotion=Attacking(originalLogicalMs);long age=current==null?0:originalLogicalMs-current.Start;bool fire=false;if(current!=null&&current.Motion=="attack"&&!current.Cancelled&&age>=380&&!current.Fired){current.Fired=true;fire=delivered.Add(current.Id);}var d=attackMotion?attack:idle;long elapsed=attackMotion?age:(current!=null&&current.Motion=="attack"?Math.Max(0,age-1040):age)%1440;frame=0;while(frame<11&&elapsed>=d[frame])elapsed-=d[frame++];return fire;}
  public long FireAge(long now)=>current==null||current.Cancelled||!current.Fired?-1:now-current.Start-380;
  public JObject Capture()=>new JObject{["version"]="kyle-visual-timeline.v1",["lastMs"]=last,["current"]=current==null?JValue.CreateNull():new JValue(current.Id),["cues"]=new JArray(cues.Values.Select(c=>c.Capture()))};
  // Preserve locally delivered visual receipts across a rollback on this presentation owner.
  public void Restore(JObject snapshot){if(snapshot==null||snapshot.Count!=4||(string)snapshot["version"]!="kyle-visual-timeline.v1"||snapshot["lastMs"]?.Type!=JTokenType.Integer||(long)snapshot["lastMs"]<0||!(snapshot["cues"] is JArray rows)||rows.Count>Capacity||snapshot["current"]==null||(snapshot["current"].Type!=JTokenType.String&&snapshot["current"].Type!=JTokenType.Null))throw new ArgumentException("Invalid visual snapshot");var restored=new Dictionary<string,Cue>();foreach(var t in rows){if(!(t is JObject row)||row.Count!=6||row["startMs"]?.Type!=JTokenType.Integer||row["facing"]?.Type!=JTokenType.Integer||row["fired"]?.Type!=JTokenType.Boolean||row["cancelled"]?.Type!=JTokenType.Boolean)throw new ArgumentException("Invalid visual receipt");var state=new CombatUnitAnimationState("op_kyle",CombatUnitRole.Operator,(string)row["motion"],(string)row["id"]);var probe=new KylePresentationTimeline(idle,attack);probe.Begin(state,(KyleFacing)(int)row["facing"],(long)row["startMs"]);var cue=probe.current;cue.Fired=(bool)row["fired"];cue.Cancelled=(bool)row["cancelled"];if(cue.Fired&&(cue.Motion!="attack"||(long)snapshot["lastMs"]<cue.Start+380)||restored.ContainsKey(cue.Id))throw new ArgumentException("Invalid visual fire receipt");if(identities.TryGetValue(cue.Id,out var original)&&(original.Start!=cue.Start||original.Motion!=cue.Motion||original.Facing!=cue.Facing))throw new ArgumentException("Original cue changed");restored.Add(cue.Id,cue);}
   if(identities.Keys.Union(restored.Keys).Count()>Capacity||restored.Values.Any(c=>(long)snapshot["lastMs"]<c.Start))throw new ArgumentException("Invalid visual identity ledger");string id=(string)snapshot["current"];if(id!=null&&!restored.ContainsKey(id)||id!=null&&(long)snapshot["lastMs"]<restored[id].Start)throw new ArgumentException("Missing current visual cue");foreach(var cue in restored.Values){if(!identities.ContainsKey(cue.Id))identities.Add(cue.Id,cue);if(cue.Fired)delivered.Add(cue.Id);}cues.Clear();foreach(var pair in restored)cues.Add(pair.Key,pair.Value);current=id==null?null:cues[id];last=(long)snapshot["lastMs"];
  }
 }
}